public class Late {
    static long directKB() {
        var beans = ManagementFactory.getPlatformMXBeans(BufferPoolMXBean.class);
        for (var b : beans) if (b.getName().equals("direct")) return b.getMemoryUsed() >> 10;
        return -1;
    }
    public static void main(String[] a) throws Exception {
        boolean gc = a[0].equals("gc");
        for (int i = 1; i <= 2000; i++) {
            ByteBuffer b = ByteBuffer.allocateDirect(1 << 20);   // 잡고 바로 버린다
            b.put(0, (byte) i);
            if (i % 500 == 0) {
                if (gc) { System.gc(); Thread.sleep(120); }
                System.out.printf("  %4d개 뒤   직접버퍼 %,7d KB%n", i, directKB());
            }
        }
    }
}

# --- 1) GC 를 안 부를 때 ---

$ java -Xmx2g -cp out Late nogc
  시작        직접버퍼       0 KB
   500개 뒤   직접버퍼 512,000 KB
  1000개 뒤   직접버퍼 1,024,000 KB
  1500개 뒤   직접버퍼 1,536,000 KB
  2000개 뒤   직접버퍼 2,048,000 KB
  끝          직접버퍼 2,048,000 KB     <- 2GB 가 그대로 남았다

